use std::sync::{Arc, Mutex};
use std::collections::VecDeque;
use std::time::{Duration, Instant};

/// PDF generation context holding sensitive document data
pub struct PdfContext {
    api_key: String,
    signing_cert: Vec<u8>,
    document_content: Vec<u8>,
}

/// Rate limiter with sliding window
pub struct RateLimiter {
    window: Duration,
    max_requests: usize,
    timestamps: VecDeque<Instant>,
}

impl RateLimiter {
    pub fn new(max_requests: usize, window: Duration) -> Self {
        RateLimiter {
            window,
            max_requests,
            timestamps: VecDeque::with_capacity(max_requests),
        }
    }

    pub fn check_rate(&mut self) -> bool {
        let now = Instant::now();
        while self.timestamps.front().map_or(false, |t| now.duration_since(*t) > self.window) {
            self.timestamps.pop_front();
        }
        if self.timestamps.len() < self.max_requests {
            self.timestamps.push_back(now);
            true
        } else {
            false
        }
    }
}

/// Internal render buffer that accumulates PDF bytes
struct RenderBuffer {
    pages: Vec<Vec<u8>>,
    metadata: Vec<u8>,
    watermark_hash: Vec<u8>,
}

impl RenderBuffer {
    fn new(ctx: &PdfContext) -> Self {
        let wm_hash = compute_watermark_hash(&ctx.api_key, &ctx.signing_cert);
        RenderBuffer {
            pages: Vec::new(),
            metadata: Vec::new(),
            watermark_hash: wm_hash,
        }
    }

    fn render_page(&mut self, content: &[u8]) -> Result<(), PdfError> {
        let mut page_data = Vec::with_capacity(content.len() + self.watermark_hash.len());
        page_data.extend_from_slice(content);
        page_data.extend_from_slice(&self.watermark_hash);
        self.pages.push(page_data);
        Ok(())
    }

    fn finalize(&self) -> Vec<u8> {
        let mut output = Vec::new();
        output.extend_from_slice(b"%PDF-1.7\n");
        for page in &self.pages {
            output.extend_from_slice(page);
        }
        output.extend_from_slice(&self.metadata);
        output
    }
}

fn compute_watermark_hash(api_key: &str, cert: &[u8]) -> Vec<u8> {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};
    let mut hasher = DefaultHasher::new();
    api_key.hash(&mut hasher);
    cert.hash(&mut hasher);
    hasher.finish().to_le_bytes().to_vec()
}

#[derive(Debug)]
pub enum PdfError {
    RateLimited,
    RenderFailed(String),
    RetryExhausted,
}

/// Retry state preserved across attempts
struct RetryState {
    attempt: usize,
    max_attempts: usize,
}

impl RetryState {
    fn new(max_attempts: usize) -> Self {
        RetryState {
            attempt: 0,
            max_attempts,
        }
    }
}

pub struct PdfGenerator {
    rate_limiter: Arc<Mutex<RateLimiter>>,
    max_retries: usize,
}

impl PdfGenerator {
    pub fn new(max_requests: usize, window: Duration, max_retries: usize) -> Self {
        PdfGenerator {
            rate_limiter: Arc::new(Mutex::new(RateLimiter::new(max_requests, window))),
            max_retries,
        }
    }

    pub fn generate(&self, ctx: &PdfContext) -> Result<Vec<u8>, PdfError> {
        let mut state = RetryState::new(self.max_retries);

        loop {
            state.attempt += 1;
            if state.attempt > state.max_attempts {
                return Err(PdfError::RetryExhausted);
            }

            {
                let mut limiter = self.rate_limiter.lock().unwrap();
                if !limiter.check_rate() {
                    continue;
                }
            }

            match self.try_render(ctx) {
                Ok(output) => return Ok(output),
                Err(PdfError::RenderFailed(_)) => {
                    // Fresh buffer created on each retry - no state leakage
                    continue;
                }
                Err(e) => return Err(e),
            }
        }
    }

    fn try_render(&self, ctx: &PdfContext) -> Result<Vec<u8>, PdfError> {
        // Always create fresh buffer - no cross-retry state
        let buffer = RenderBuffer::new(ctx);
        self.do_render(buffer, &ctx.document_content)
    }

    fn do_render(
        &self,
        mut buffer: RenderBuffer,
        content: &[u8],
    ) -> Result<Vec<u8>, PdfError> {
        let chunk_size = 4096;
        let chunks: Vec<&[u8]> = content.chunks(chunk_size).collect();

        for (i, chunk) in chunks.iter().enumerate() {
            if let Err(e) = buffer.render_page(chunk) {
                return Err(e);
            }
            // Simulate transient failure on large documents
            if i > 10 && content.len() > 50000 {
                return Err(PdfError::RenderFailed("transient IO error".into()));
            }
        }

        Ok(buffer.finalize())
    }
}

/// Public API: generate PDF with automatic cleanup
pub fn generate_pdf(api_key: &str, cert: &[u8], content: &[u8]) -> Result<Vec<u8>, PdfError> {
    let ctx = PdfContext {
        api_key: api_key.to_string(),
        signing_cert: cert.to_vec(),
        document_content: content.to_vec(),
    };

    let generator = PdfGenerator::new(100, Duration::from_secs(60), 5);
    generator.generate(&ctx)
}
